-- The schema of a fresh install at SCHEMA_VERSION 10. Do not edit by hand: regenerate with
-- python tools/pin_schema.py (see the schema versions checklist in app.py).
index audit_hh: CREATE INDEX audit_hh ON audit(household_id, at)
index audit_sid: CREATE INDEX audit_sid ON audit(session_id)
index bill_snapshots_sid: CREATE INDEX bill_snapshots_sid ON bill_snapshots(session_id)
index charges_sid: CREATE INDEX charges_sid ON charges(session_id)
index documents_sid: CREATE INDEX documents_sid ON documents(session_id)
index expenses_sid: CREATE INDEX expenses_sid ON expenses(session_id)
index lines_sid: CREATE INDEX lines_sid ON lines(session_id)
index log_hh: CREATE INDEX log_hh ON log(household_id, at)
index log_sid: CREATE INDEX log_sid ON log(session_id)
index payments_sid: CREATE INDEX payments_sid ON payments(session_id)
index people_hh: CREATE INDEX people_hh ON people(household_id)
index photo_files_name: CREATE UNIQUE INDEX photo_files_name ON photo_files(session_id, kind, name)
index photo_files_sid: CREATE INDEX photo_files_sid ON photo_files(session_id, kind)
index print_lab_costs_order: CREATE INDEX print_lab_costs_order ON print_lab_costs(order_id)
index print_orders_sid: CREATE INDEX print_orders_sid ON print_orders(session_id)
index quote_versions_number: CREATE UNIQUE INDEX quote_versions_number ON quote_versions(number)
index sessions_event: CREATE INDEX sessions_event ON sessions(event_id)
index sessions_gallery_id: CREATE UNIQUE INDEX sessions_gallery_id ON sessions(gallery_id) WHERE gallery_id IS NOT NULL AND gallery_id != ''
index sessions_hh: CREATE INDEX sessions_hh ON sessions(household_id)
index sessions_stage: CREATE INDEX sessions_stage ON sessions(stage)
index stage_log_sid: CREATE INDEX stage_log_sid ON stage_log(session_id)
index step_closes_sid: CREATE INDEX step_closes_sid ON step_closes(session_id)
index tasks_eid: CREATE INDEX tasks_eid ON tasks(event_id)
index tasks_sid: CREATE INDEX tasks_sid ON tasks(session_id)
index tax_adjustments_sid: CREATE INDEX tax_adjustments_sid ON tax_adjustments(session_id)
index write_offs_sid: CREATE INDEX write_offs_sid ON write_offs(session_id)
table audit: CREATE TABLE audit ( id INTEGER PRIMARY KEY, at TEXT NOT NULL, household_id INTEGER, session_id INTEGER, event_id INTEGER, action TEXT NOT NULL, note TEXT DEFAULT '', who TEXT DEFAULT 'Owner', route TEXT DEFAULT '', data TEXT DEFAULT '')
table bill_snapshots: CREATE TABLE bill_snapshots (number TEXT PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, at TEXT, sig TEXT, data TEXT NOT NULL, html TEXT)
table books: CREATE TABLE books ( id INTEGER PRIMARY KEY, received TEXT, amount REAL, tax REAL DEFAULT 0, type TEXT, kind TEXT, "tax_parts" TEXT)
table call_sheets: CREATE TABLE call_sheets ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, notes TEXT NOT NULL DEFAULT '', client_contact INTEGER NOT NULL DEFAULT 0)
table calsend_events: CREATE TABLE calsend_events (ident TEXT PRIMARY KEY, rid TEXT NOT NULL DEFAULT '', etag TEXT NOT NULL DEFAULT '', digest TEXT NOT NULL DEFAULT '', day TEXT NOT NULL DEFAULT '')
table calsend_secret: CREATE TABLE calsend_secret (name TEXT PRIMARY KEY, value BLOB NOT NULL, at REAL)
table charges: CREATE TABLE charges (id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, at TEXT NOT NULL, amount REAL NOT NULL, number TEXT NOT NULL DEFAULT '', label TEXT NOT NULL DEFAULT '')
table client_end_contact: CREATE TABLE client_end_contact (household_id INTEGER PRIMARY KEY REFERENCES households(id) ON DELETE CASCADE, since TEXT NOT NULL)
table client_labels: CREATE TABLE client_labels (household_id INTEGER NOT NULL REFERENCES households(id) ON DELETE CASCADE, label TEXT NOT NULL, PRIMARY KEY (household_id, label))
table credit_uses: CREATE TABLE credit_uses (id INTEGER PRIMARY KEY, credit_id INTEGER REFERENCES deposit_credits(id) ON DELETE CASCADE, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, amount REAL NOT NULL, at TEXT NOT NULL, refund_id INTEGER, payment_id INTEGER)
table crew: CREATE TABLE crew ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', rate_cents INTEGER, created TEXT DEFAULT CURRENT_TIMESTAMP)
table deposit_credits: CREATE TABLE deposit_credits (id INTEGER PRIMARY KEY, household_id INTEGER REFERENCES households(id) ON DELETE CASCADE, from_session INTEGER REFERENCES sessions(id) ON DELETE CASCADE, amount REAL NOT NULL, at TEXT NOT NULL)
table doc_numbers: CREATE TABLE doc_numbers (session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, number TEXT NOT NULL UNIQUE, issued TEXT, PRIMARY KEY (session_id, kind))
table doc_snapshots: CREATE TABLE doc_snapshots ( kind TEXT NOT NULL, ref INTEGER NOT NULL, at TEXT, data TEXT NOT NULL, PRIMARY KEY (kind, ref))
table doc_snapshots_old: CREATE TABLE doc_snapshots_old ( kind TEXT NOT NULL, ref INTEGER NOT NULL, at TEXT, data TEXT NOT NULL, moved TEXT)
table documents: CREATE TABLE documents ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, about_person INTEGER REFERENCES people(id) ON DELETE SET NULL, signer TEXT DEFAULT '', status TEXT DEFAULT 'needed', sent TEXT, signed TEXT, note TEXT DEFAULT '', "covers" TEXT DEFAULT '', "covers_kind" TEXT DEFAULT '')
table equipment: CREATE TABLE equipment ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, serial TEXT DEFAULT '', bought TEXT, price_cents INTEGER, receipt_fid TEXT, renews TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP)
table events: CREATE TABLE events ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, date TEXT, venue TEXT DEFAULT '', notes TEXT DEFAULT '', demo INTEGER DEFAULT 0, "billing" TEXT DEFAULT 'free', "rights" TEXT DEFAULT 'families', "rights_note" TEXT DEFAULT '', "payer_hid" INTEGER, "contact_hid" INTEGER, "family_price" REAL, "attendees" TEXT DEFAULT 'families', "org_price" REAL, "org_per" TEXT DEFAULT 'person', "family_tax_in" INTEGER DEFAULT 0)
table expenses: CREATE TABLE expenses ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, date TEXT, label TEXT NOT NULL, amount REAL DEFAULT 0, miles REAL DEFAULT 0, "rate" REAL, "corrects" INTEGER, "late_from" TEXT, "note" TEXT DEFAULT '')
table fee_schedules: CREATE TABLE fee_schedules (id INTEGER PRIMARY KEY AUTOINCREMENT, created TEXT, items TEXT NOT NULL, note TEXT DEFAULT '')
table galleries: CREATE TABLE galleries ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, source_dir TEXT DEFAULT '', built_at TEXT, n_files INTEGER DEFAULT 0, out_dir TEXT DEFAULT '', key TEXT NOT NULL, "picks_hash" TEXT DEFAULT '', "limits_days" INTEGER, "limits_contact" TEXT, "dark_at" TEXT, "restored_at" TEXT, "restore_days" INTEGER, "restore_once" TEXT, "host_fp" TEXT, "link_base" TEXT, "moved_from" TEXT, "ekey" TEXT DEFAULT '', "sealed_gen" INTEGER DEFAULT 0, "page_set" TEXT, "link_was" TEXT, "was_open" INTEGER DEFAULT 0, "was_fp" TEXT, "draft_n" INTEGER, "draft_at" TEXT, "proof" INTEGER DEFAULT 0, "prune_due" TEXT, "built_upto" TEXT, "adopted" TEXT, "adopted_old" INTEGER DEFAULT 0, "adopted_fmt" TEXT, "adopt_until" TEXT, "photos_home_at" TEXT, "close_on" TEXT, "brand_fp" TEXT, "cw_fixed" TEXT, "upload_state" TEXT DEFAULT '', "uploaded_at" TEXT, "removed_at" TEXT, "upload_error" TEXT DEFAULT '')
table gallery_cards: CREATE TABLE gallery_cards ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, code TEXT NOT NULL, card_id TEXT NOT NULL, written_at TEXT, n_files INTEGER DEFAULT 0, written_to TEXT DEFAULT '')
table gallery_leftovers: CREATE TABLE gallery_leftovers ( gallery_id TEXT NOT NULL, host_fp TEXT NOT NULL, added TEXT, PRIMARY KEY (gallery_id, host_fp))
table households: CREATE TABLE households ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT DEFAULT '', source TEXT DEFAULT '', referred_by INTEGER REFERENCES households(id), notes TEXT DEFAULT '', demo INTEGER DEFAULT 0, created TEXT DEFAULT CURRENT_TIMESTAMP, "company" TEXT DEFAULT '', "business" INTEGER, "tax_exempt" INTEGER DEFAULT 0, "tax_cert" TEXT DEFAULT '')
table id_marks: CREATE TABLE id_marks (name TEXT PRIMARY KEY, n INTEGER NOT NULL)
table invoice_sent: CREATE TABLE invoice_sent (session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, number TEXT NOT NULL, sig TEXT NOT NULL)
table letters_printed: CREATE TABLE letters_printed ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, at TEXT NOT NULL)
table lines: CREATE TABLE lines ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, label TEXT NOT NULL, amount REAL NOT NULL DEFAULT 0, "kind" TEXT DEFAULT 'custom', "fee_key" TEXT DEFAULT '', "qty" REAL DEFAULT 1, "unit" REAL, "taxable" INTEGER DEFAULT 1, "tax_key" TEXT, "untaxed" TEXT DEFAULT '')
table log: CREATE TABLE log ( id INTEGER PRIMARY KEY, household_id INTEGER REFERENCES households(id) ON DELETE CASCADE, session_id INTEGER REFERENCES sessions(id) ON DELETE SET NULL, at TEXT DEFAULT CURRENT_TIMESTAMP, channel TEXT DEFAULT 'note', summary TEXT NOT NULL, written_at TEXT)
table packing_lists: CREATE TABLE packing_lists (type_key TEXT PRIMARY KEY, lines TEXT NOT NULL DEFAULT '[]')
table packing_ticks: CREATE TABLE packing_ticks ( session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, line TEXT NOT NULL, PRIMARY KEY (session_id, line))
table payments: CREATE TABLE payments ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT DEFAULT 'deposit', amount REAL NOT NULL, received TEXT, method TEXT DEFAULT '', "voided" TEXT, "ref" TEXT DEFAULT '', "tax" REAL, "taxable" REAL, "note" TEXT DEFAULT '', "corrects" INTEGER, "tax_parts" TEXT)
table people: CREATE TABLE people ( id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id) ON DELETE CASCADE, name TEXT NOT NULL, role TEXT DEFAULT 'adult', is_minor INTEGER DEFAULT 0, grad_year INTEGER, email TEXT DEFAULT '', phone TEXT DEFAULT '', notes TEXT DEFAULT '', "relation" TEXT DEFAULT '', "gender" TEXT DEFAULT '', "birth_year" INTEGER, "birth_date" TEXT, "age_approx" INTEGER DEFAULT 0, "minor_box" INTEGER)
table photo_deleted: CREATE TABLE photo_deleted (id TEXT PRIMARY KEY)
table photo_files: CREATE TABLE photo_files ( id TEXT PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, name TEXT NOT NULL, size INTEGER NOT NULL, received INTEGER DEFAULT 0, ct_len INTEGER DEFAULT 0, records INTEGER DEFAULT 0, fkey TEXT NOT NULL, state TEXT DEFAULT 'partial', created TEXT DEFAULT CURRENT_TIMESTAMP, done_at TEXT, mirrored TEXT, "key_trail" TEXT DEFAULT '[]')
table photo_orphans: CREATE TABLE photo_orphans (id TEXT PRIMARY KEY, first_seen TEXT NOT NULL)
table price_list_items: CREATE TABLE price_list_items (id TEXT PRIMARY KEY, label TEXT NOT NULL, w REAL NOT NULL, h REAL NOT NULL, finish TEXT DEFAULT '', each_cents INTEGER, cost_cents INTEGER, cost_from TEXT DEFAULT '', cost_date TEXT DEFAULT '', price_set INTEGER DEFAULT 0, ppi_hide INTEGER DEFAULT 150, ppi_mark INTEGER DEFAULT 200, offered INTEGER DEFAULT 1, lab TEXT DEFAULT '{}', sort INTEGER DEFAULT 0)
table price_list_versions: CREATE TABLE price_list_versions (plv INTEGER PRIMARY KEY, json TEXT NOT NULL, saved_at TEXT)
table print_books: CREATE TABLE print_books (id INTEGER PRIMARY KEY, day TEXT NOT NULL, what TEXT NOT NULL, amount_cents INTEGER NOT NULL)
table print_galleries: CREATE TABLE print_galleries (session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, gid TEXT, off INTEGER DEFAULT 0, offer_sig TEXT DEFAULT '', offered_at TEXT, ever INTEGER DEFAULT 0, host_fp TEXT, "proofs" INTEGER DEFAULT 0)
table print_lab_costs: CREATE TABLE print_lab_costs (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES print_orders(id) ON DELETE CASCADE, day TEXT NOT NULL, kind TEXT NOT NULL, lab_name TEXT DEFAULT '', lab_number TEXT DEFAULT '', products INTEGER DEFAULT 0, shipping INTEGER DEFAULT 0, tax INTEGER DEFAULT 0, other INTEGER DEFAULT 0, reverses INTEGER, at TEXT)
table print_lab_secrets: CREATE TABLE print_lab_secrets (name TEXT PRIMARY KEY, value TEXT)
table print_order_lines: CREATE TABLE print_order_lines (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES print_orders(id) ON DELETE CASCADE, n INTEGER NOT NULL, photo_file TEXT NOT NULL, photo_name TEXT DEFAULT '', item_id TEXT NOT NULL, label TEXT DEFAULT '', w REAL, h REAL, finish TEXT DEFAULT '', qty INTEGER NOT NULL, crop TEXT NOT NULL, turn INTEGER DEFAULT 0, each_cents INTEGER NOT NULL, ppi INTEGER DEFAULT 0, crop_confirmed INTEGER DEFAULT 0, soft_confirmed INTEGER DEFAULT 0, shown_cents INTEGER)
table print_order_oids: CREATE TABLE print_order_oids (oid TEXT PRIMARY KEY, gid TEXT, first_seen TEXT)
table print_orders: CREATE TABLE print_orders (id INTEGER PRIMARY KEY, oid TEXT NOT NULL UNIQUE, gid TEXT NOT NULL, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, state TEXT NOT NULL, prev_state TEXT, contact_id INTEGER REFERENCES people(id) ON DELETE SET NULL, guest INTEGER DEFAULT 0, bill_name TEXT DEFAULT '', bill_email TEXT DEFAULT '', payload TEXT NOT NULL, env_sha256 TEXT, plv INTEGER, browser_at TEXT, host_mtime TEXT, collected_at TEXT, invoice_number TEXT, invoice_issued TEXT, invoice_data TEXT, invoice_html TEXT, invoice_void TEXT, ship_lab_cents INTEGER, ship_cents INTEGER, tax_rate REAL, tax_area TEXT, flags TEXT DEFAULT '{}', before_payment INTEGER DEFAULT 0, prepared_at TEXT, lab_id TEXT, lab_words TEXT DEFAULT '', lab_name TEXT DEFAULT '', lab_orders TEXT DEFAULT '[]', cost_products INTEGER, cost_shipping INTEGER, cost_tax INTEGER, cost_other INTEGER, lab_tax_pending INTEGER DEFAULT 0, ordered_at TEXT, shipped_at TEXT, delivered_at TEXT, closed_at TEXT, remake_note TEXT DEFAULT '', cancel_lab TEXT DEFAULT '', told_shipped TEXT, reduced_at TEXT, lab_problem TEXT DEFAULT '', ship_by_hand INTEGER DEFAULT 0)
table print_payments: CREATE TABLE print_payments (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES print_orders(id) ON DELETE CASCADE, kind TEXT NOT NULL, amount_cents INTEGER NOT NULL, received TEXT NOT NULL, method TEXT DEFAULT '', ref TEXT DEFAULT '', voided TEXT, "corrects" INTEGER, "note" TEXT DEFAULT '')
table quote_marks: CREATE TABLE quote_marks (vid INTEGER PRIMARY KEY REFERENCES quote_versions(id) ON DELETE CASCADE, session_id INTEGER, at TEXT NOT NULL)
table quote_replacements: CREATE TABLE quote_replacements (id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, at TEXT NOT NULL, old_vid INTEGER, old_total REAL NOT NULL DEFAULT 0, old_lines TEXT NOT NULL DEFAULT '[]', agreement TEXT NOT NULL DEFAULT '[]', new_vid INTEGER, booked_at TEXT)
table quote_versions: CREATE TABLE quote_versions (id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, at TEXT, schedule_id INTEGER, expires TEXT, data TEXT NOT NULL, "number" TEXT)
table quotes: CREATE TABLE quotes (session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, schedule_id INTEGER REFERENCES fee_schedules(id), discount_pct REAL DEFAULT 0, discount_reason TEXT DEFAULT '', created TEXT, expires TEXT, "sent" TEXT)
table refund_credits: CREATE TABLE refund_credits (payment_id INTEGER PRIMARY KEY REFERENCES payments(id) ON DELETE CASCADE, session_id INTEGER, amount REAL NOT NULL)
table retention: CREATE TABLE retention ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, raw_dir TEXT DEFAULT '', keep_until TEXT, purged_at TEXT, "early_note" TEXT DEFAULT '', "sealed_at" TEXT, "unsealed_dir" TEXT DEFAULT '', "unsealed_at" TEXT, "notice" TEXT DEFAULT '{}', "keep_days" INTEGER)
table sealed_seen: CREATE TABLE sealed_seen ( purpose TEXT NOT NULL, item TEXT NOT NULL, link TEXT NOT NULL DEFAULT '', first_seen TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (purpose, link, item))
table session_crew: CREATE TABLE session_crew ( id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, crew_id INTEGER NOT NULL REFERENCES crew(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT '', call_time TEXT NOT NULL DEFAULT '', expense_id INTEGER REFERENCES expenses(id) ON DELETE SET NULL, UNIQUE (session_id, crew_id))
table session_people: CREATE TABLE session_people ( session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, person_id INTEGER REFERENCES people(id) ON DELETE CASCADE, PRIMARY KEY (session_id, person_id))
table session_taxes: CREATE TABLE session_taxes (session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, key TEXT NOT NULL, name TEXT, rate REAL, included INTEGER DEFAULT 0, pick INTEGER, PRIMARY KEY (session_id, key))
table sessions: CREATE TABLE sessions ( id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id) ON DELETE CASCADE, event_id INTEGER REFERENCES events(id) ON DELETE SET NULL, type TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'inquiry', title TEXT DEFAULT '', shoot_date TEXT, start_time TEXT DEFAULT '', stops TEXT DEFAULT '', intake TEXT DEFAULT '{}', notes TEXT DEFAULT '', gallery_id TEXT DEFAULT '', gallery_built TEXT, letter_mailed TEXT, first_visit TEXT, extension_used INTEGER DEFAULT 0, sd_shipped TEXT, favorites TEXT DEFAULT '', veto TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, stage_changed TEXT DEFAULT CURRENT_TIMESTAMP, "duration_min" INTEGER, "lost_reason" TEXT DEFAULT '', "hold_stage" TEXT, "portfolio_no" INTEGER DEFAULT 0, "delivery_method" TEXT, "gallery_codeword" TEXT DEFAULT '', "tax_exempt" INTEGER DEFAULT 0, "tax_area" TEXT, "retouch_picks" TEXT DEFAULT '', "payer_event" INTEGER, "date_tentative" INTEGER DEFAULT 0, "plan_of" INTEGER, "po_number" TEXT DEFAULT '', "lic_term" TEXT DEFAULT '', "lic_territory" TEXT DEFAULT '', "lic_exclusive" INTEGER DEFAULT 0, "trade_copies" INTEGER DEFAULT 0, "priced_on" TEXT, "tax_rate" REAL, "tax_area_locked" TEXT, "deposit_booked" REAL, "pencil_until" TEXT, "installments" INTEGER, "resched_settled" INTEGER DEFAULT 0, "plan_dates" TEXT, "refund_release" TEXT)
table settings: CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT)
table side_keys: CREATE TABLE side_keys (name TEXT PRIMARY KEY, key TEXT NOT NULL)
table sqlite_sequence: CREATE TABLE sqlite_sequence(name,seq)
table stage_log: CREATE TABLE stage_log ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, stage TEXT NOT NULL, at TEXT DEFAULT (date('now','localtime')), era TEXT)
table step_closes: CREATE TABLE step_closes ( session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, step TEXT NOT NULL, outcome TEXT NOT NULL, at TEXT DEFAULT (date('now','localtime')), note TEXT DEFAULT '', PRIMARY KEY (session_id, step))
table studio_files: CREATE TABLE studio_files ( name TEXT NOT NULL, host_fp TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT, session_id INTEGER, photo_id TEXT, at TEXT, PRIMARY KEY (name, host_fp))
table studio_inquiries: CREATE TABLE studio_inquiries ( sha256 TEXT PRIMARY KEY, session_id INTEGER, household_id INTEGER, received TEXT, outcome TEXT NOT NULL, "sender" TEXT, "contact_id" INTEGER, "log_id" INTEGER, "filed" TEXT)
table studio_inquiry_review: CREATE TABLE studio_inquiry_review ( id INTEGER PRIMARY KEY, sha256 TEXT UNIQUE NOT NULL, fields TEXT NOT NULL, received TEXT NOT NULL, "replied" TEXT)
table studio_kept: CREATE TABLE studio_kept ( id INTEGER PRIMARY KEY, host_fp TEXT NOT NULL, at TEXT NOT NULL, folder TEXT NOT NULL, files TEXT NOT NULL, put_back TEXT)
table studio_photos: CREATE TABLE studio_photos ( id TEXT PRIMARY KEY, source TEXT NOT NULL, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, file_id TEXT, name TEXT DEFAULT '', alt TEXT DEFAULT '', sort INTEGER DEFAULT 0, data BLOB, first_year INTEGER, added TEXT)
table tasks: CREATE TABLE tasks ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, title TEXT NOT NULL, offset_days INTEGER, due TEXT, done TEXT, sort INTEGER DEFAULT 0, stage TEXT, own INTEGER DEFAULT 0, event_id INTEGER REFERENCES events(id) ON DELETE CASCADE, outcome TEXT, outcome_note TEXT)
table tax_adjustments: CREATE TABLE tax_adjustments (id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, at TEXT NOT NULL, tax REAL NOT NULL, taxable REAL NOT NULL DEFAULT 0, why TEXT NOT NULL DEFAULT '', "tax_parts" TEXT)
table users: CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, pw_hash TEXT NOT NULL DEFAULT '', totp_secret TEXT NOT NULL, recovery TEXT NOT NULL DEFAULT '[]', created TEXT, failed INTEGER DEFAULT 0, locked_until TEXT, "totp_last" INTEGER DEFAULT 0)
table vault_keys: CREATE TABLE vault_keys (session_id INTEGER PRIMARY KEY, pub TEXT NOT NULL, wrapped TEXT NOT NULL, created TEXT, orphaned TEXT, lost_wrapped TEXT)
table vault_objects: CREATE TABLE vault_objects (id INTEGER PRIMARY KEY, session_id INTEGER, kind TEXT NOT NULL, name TEXT NOT NULL, backend TEXT NOT NULL, size INTEGER, sha256 TEXT, created TEXT, deleted TEXT)
table vault_secondary: CREATE TABLE vault_secondary (name TEXT PRIMARY KEY, size INTEGER, sha256 TEXT, copied TEXT)
table write_offs: CREATE TABLE write_offs (id INTEGER PRIMARY KEY, session_id INTEGER, amount REAL NOT NULL, at TEXT NOT NULL, why TEXT NOT NULL DEFAULT 'waived', "note" TEXT DEFAULT '')
